import{_ as e,o as i,c as a,ag as t}from"./chunks/framework.8tqBsFWt.js";const k=JSON.parse('{"title":"Local Development","description":"","frontmatter":{},"headers":[],"relativePath":"operations/local-development.md","filePath":"operations/local-development.md"}'),n={name:"operations/local-development.md"};function o(l,s,d,r,h,p){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="local-development" tabindex="-1">Local Development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local Development&quot;">​</a></h1><p>How to run VERA on your machine, including the CSS/design-token build step.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><strong>Node.js</strong> (the version Railway runs; an LTS ≥ 18 is safe) and <strong>npm</strong>.</li><li><strong>PostgreSQL</strong> — a local instance or a Supabase/hosted connection string. VERA is Postgres-only; there is no SQLite/in-memory fallback for running the app (tests mock the DB, so tests need no database).</li><li>An <strong>Anthropic API key</strong> (only needed if you want box-2 / model-backed replies to work; box-1 deterministic paths and the console run without it).</li></ul><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/talktalkmake/VERA.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VERA</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="_2-environment-variables" tabindex="-1">2. Environment variables <a class="header-anchor" href="#_2-environment-variables" aria-label="Permalink to &quot;2. Environment variables&quot;">​</a></h2><p>Create a <code>.env</code> file in the repo root. The full list and meaning of every variable is in <a href="https://github.com/talktalkmake/VERA/blob/main/CLAUDE.md" target="_blank" rel="noreferrer">CLAUDE.md</a> under <strong>Required env vars</strong>; the minimum to boot locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-ant-...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # optional locally; required for model replies</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ADMIN_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">some-long-random-string</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # gates /admin and /status</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TENANTS_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./tenants.dev.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # default; the dev tenant config</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # runtime role (vera_app in prod)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MIGRATION_DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">postgres://...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # privileged role for migrations; in dev set = DATABASE_URL</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Web console (/console) — required or /console* returns 503:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONSOLE_SESSION_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONSOLE_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:3000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># OAuth login (optional locally; without it the console login page has no provider button):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GOOGLE_OAUTH_CLIENT_ID=...</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GOOGLE_OAUTH_CLIENT_SECRET=...</span></span></code></pre></div><blockquote><p><strong>Do not set <code>ERROR_REPORTER_ENABLED</code> in dev</strong> — it must stay off outside production (it files GitHub issues). <code>NODE_ENV=test</code> short-circuits it during tests regardless.</p></blockquote><p>Tenant config (Slack tokens, audit channel, timezone per tenant) lives in <code>tenants.dev.json</code>. See <a href="https://github.com/talktalkmake/VERA/blob/main/TENANTS.md" target="_blank" rel="noreferrer">TENANTS.md</a> for the shape; you can edit tenants in-browser at <code>/admin</code> once running.</p><blockquote><p>Rotating any of these secrets (on compromise, offboarding, or a periodic cadence)? Follow the <a href="./secret-rotation.html">secret rotation runbook</a>.</p></blockquote><h2 id="_3-database-migrations" tabindex="-1">3. Database &amp; migrations <a class="header-anchor" href="#_3-database-migrations" aria-label="Permalink to &quot;3. Database &amp; migrations&quot;">​</a></h2><p>VERA uses <code>node-pg-migrate</code>. Apply the schema before first boot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # applies pending migrations against MIGRATION_DATABASE_URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:down</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # roll back the last migration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_migration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # scaffold a new migration file</span></span></code></pre></div><p>In production, <code>npm start</code> (via <code>scripts/start.js</code>) runs <code>migrate up</code> automatically before booting. Locally, run <code>migrate:up</code> yourself after pulling new migrations.</p><blockquote><p><strong>Why two database URLs?</strong> <code>migrations/0016_app_role.js</code> splits roles: the privileged role (<code>MIGRATION_DATABASE_URL</code>) can create tables and manage migration bookkeeping; the runtime role (<code>DATABASE_URL</code> → <code>vera_app</code>, <code>NOBYPASSRLS</code>) only has <code>SELECT/INSERT/UPDATE/DELETE</code>. With a single local role, point both at the same connection string.</p></blockquote><h2 id="_4-run-the-app" tabindex="-1">4. Run the app <a class="header-anchor" href="#_4-run-the-app" aria-label="Permalink to &quot;4. Run the app&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # nodemon — auto-reloads index.js on change</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # production entrypoint: runs migrations (if MIGRATION_DATABASE_URL set) then index.js</span></span></code></pre></div><p>The app serves Slack (Socket Mode), the internal MCP server, the web console at <code>http://localhost:3000/console</code>, <code>/admin</code>, and <code>/status</code>.</p><h2 id="_5-css-design-tokens-build-step" tabindex="-1">5. CSS / design tokens (build step) <a class="header-anchor" href="#_5-css-design-tokens-build-step" aria-label="Permalink to &quot;5. CSS / design tokens (build step)&quot;">​</a></h2><p><strong><code>public/tokens.css</code> is a generated, committed artifact — never edit it by hand.</strong> It is produced from the single source of truth, <a href="./../design/design-tokens.html"><code>docs/design/design-tokens.md</code></a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:tokens</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # docs/design/design-tokens.md → public/tokens.css</span></span></code></pre></div><p>How it flows:</p><ul><li><code>docs/design/design-tokens.md</code> is a markdown table of tokens (<code>color.brand</code>, <code>font.headline</code>, <code>radius.lg</code>, …). It is the <strong>only</strong> file you edit to change the palette/typography/spacing.</li><li><code>scripts/build-tokens.js</code> parses that table and regenerates <code>public/tokens.css</code>, emitting each token as a <code>--vera-*</code> CSS custom property. Colors are emitted twice: <code>--vera-color-x-hsl</code> (the <code>H, S%, L%</code> channels, for composing translucency) and <code>--vera-color-x</code> (the opaque <code>hsla(...)</code>).</li><li>The <strong>web console</strong> links the generated file via <code>&lt;link rel=&quot;stylesheet&quot; href=&quot;/static/tokens.css&quot;&gt;</code> (served from <code>public/</code>), so console styles read <code>var(--vera-*)</code>.</li><li><strong>getvera.site</strong> (the VitePress docs site) imports the same file via <code>docs/.vitepress/theme/tokens.css</code>, which maps a subset of VERA tokens onto VitePress&#39;s brand variables.</li></ul><p><strong>Workflow whenever you change a token:</strong> edit <code>docs/design/design-tokens.md</code> → run <code>npm run build:tokens</code> → commit <em>both</em> the <code>.md</code> and the regenerated <code>public/tokens.css</code>. There is a test (<code>tests/design-tokens.test.js</code>) that fails if <code>public/tokens.css</code> is out of sync with the markdown, so a stale build is caught by <code>npm test</code>.</p><h2 id="_6-tests" tabindex="-1">6. Tests <a class="header-anchor" href="#_6-tests" aria-label="Permalink to &quot;6. Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # full Jest suite (~5s, no external services — the DB and Slack are mocked)</span></span></code></pre></div><p>Tests require no database or API keys. CI/local note: a couple of model-backed simulator tests can flake on the live model; &quot;no non-flaky failures&quot; is the green bar.</p><p><strong>Every pull request now runs <code>.github/workflows/ci.yml</code>:</strong> a <code>test</code> job (<code>npm test</code>) and a <code>migrations</code> job that applies every Postgres migration from zero against a throwaway database, then runs the migrate step a second time to confirm a boot against an already-current schema is a clean no-op (it does not prove individual migrations are re-runnable). Fix a local failure before pushing — it will fail the same way on the PR.</p><h2 id="_7-docs-site-getvera-site" tabindex="-1">7. Docs site (getvera.site) <a class="header-anchor" href="#_7-docs-site-getvera-site" aria-label="Permalink to &quot;7. Docs site (getvera.site)&quot;">​</a></h2><p>The public docs site is VitePress under <code>docs/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # local preview of getvera.site with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # production build (also syncs the book outline)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # serve the production build locally</span></span></code></pre></div><p>Docs deploy automatically to <a href="https://getvera.site" target="_blank" rel="noreferrer">https://getvera.site</a> when changes under <code>docs/**</code> land on <code>main</code>.</p><h2 id="_8-verifying-a-deploy-landed" tabindex="-1">8. Verifying a deploy landed <a class="header-anchor" href="#_8-verifying-a-deploy-landed" aria-label="Permalink to &quot;8. Verifying a deploy landed&quot;">​</a></h2><p><code>GET /version</code> is unauthenticated and answers &quot;which build is actually running?&quot; in one curl — no round of code archaeology, no guessing from log timestamps:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.getvera.site/version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .started_at</span></span></code></pre></div><p>Compare against the merge time. If <code>started_at</code> is earlier than your merge, the container is behind and nothing else is worth investigating yet. To confirm the exact commit running, compare <code>commit</code> (when present — a best-effort read of <code>RAILWAY_GIT_COMMIT_SHA</code>) directly against the commit you expect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.getvera.site/version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .commit)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse origin/main)</span></span></code></pre></div><p>Silence means the container is running that commit; any output means it is behind. See the &quot;Version endpoint&quot; entry in <code>CLAUDE.md</code> for the full field list.</p><h2 id="script-reference" tabindex="-1">Script reference <a class="header-anchor" href="#script-reference" aria-label="Permalink to &quot;Script reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>Run the app with nodemon auto-reload</td></tr><tr><td><code>npm start</code></td><td>Production entrypoint (migrations + app)</td></tr><tr><td><code>npm test</code></td><td>Jest suite</td></tr><tr><td><code>npm run migrate:up</code> / <code>:down</code> / <code>:create</code></td><td>Postgres migrations</td></tr><tr><td><code>npm run build:tokens</code></td><td>Regenerate <code>public/tokens.css</code> from <code>design-tokens.md</code></td></tr><tr><td><code>npm run docs:dev</code> / <code>:build</code> / <code>:preview</code></td><td>VitePress docs site</td></tr><tr><td><code>npm run sync:book</code></td><td>Sync the book outline into the docs build (/about chapters)</td></tr></tbody></table>`,42)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
